  function apply(result,message){if(!result?.ok){toast(result?.reason||'That action could not be completed.');return false;}save();render();if(message)toast(message);return true;}
  function head(kicker,description,actions=''){return `<header class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${titles[route()]}<span aria-hidden="true">_</span></h1><p>${description}</p></div><div class="actions">${actions}</div></header>`;}
  function miniArt(name){return `<div class="mini-art" data-dither-video data-cell="2" data-dark="#00006A" data-fit="1.04"><video muted loop playsinline preload="metadata" poster="assets/mascot/${name}.poster.webp" src="assets/mascot/${name}.webm" aria-hidden="true"></video><canvas aria-hidden="true"></canvas></div>`;}
  function shell(){const r=route();$('#nav').innerHTML=routes.map(([id,name,ico])=>`<a class="nav-link" href="#/${id}" aria-label="${name}${id==='studio'&&pending().length?', '+pending().length+' to approve':''}" ${r===id?'aria-current="page"':''}>${icon(ico)}<span>${name}</span>${id==='studio'&&pending().length?`<span class="nav-count">${pending().length}</span>`:''}</a>`).join('');$('#brand-nav').setAttribute('aria-current',r==='brand'?'page':'false');$('#workspace-name').textContent=S.brand.name;{const av=$('#workspace-avatar'),sub=$('#workspace-sub');if(av)av.textContent=(S.brand.name||'?').trim()[0].toUpperCase();if(sub){const o=S.onboarding;sub.textContent=o?[(S.brand.url||'').replace(/^https?:\/\//,''),o.category].filter(Boolean).join(' / ').toUpperCase()||'YOUR BRAND':'SAMPLE WORKSPACE';}}$('#crumb').textContent=r==='overview'?'Command Center':(routes.find(x=>x[0]===r)?.[1]||'Brand');$('#queue-status').textContent=S.paused?'Publishing queue paused':'Local workspace';document.title=`${titles[r]} — Coldstart`;const sp=$('#side-promo');if(sp){const d=pixelSteps().filter(x=>x[1]).length;const hide=r==='tracking'||r==='overview';const key=hide?'hide':String(d);if(sp.dataset.k!==key){sp.dataset.k=key;sp.innerHTML=hide?'':`<a class="side-promo" href="#/tracking">${art('wave',{fit:1.2,dark:'#0000F2',light:'#F2F2F2'})}<strong>${d<4?'Pixel '+d+'/4':'Pixel live'}<b>_</b></strong><small>${d<4?'Meta can’t learn from your store until this is done.':'Browser + server events matched.'}</small><span class="btn">${d<4?'Finish setup':'View events'}</span></a>`;}}}
  const REDUCED=matchMedia('(prefers-reduced-motion: reduce)').matches;
  /* Dithered Coldie clip, same duotone treatment as the landing page. */
  const art=(name,o={})=>`<div class="art ${o.cls||''}" data-dither-video data-cell="${o.cell||2}" data-dark="${o.dark||'#00006A'}" data-light="${o.light||'#F2F2F2'}" data-fit="${o.fit||1}"${o.x!=null?` data-x="${o.x}"`:''}><video muted loop playsinline ${REDUCED?'':'autoplay'} preload="metadata" poster="assets/mascot/${name}.poster.webp" src="assets/mascot/${name}.webm" aria-hidden="true"></video><canvas aria-hidden="true"></canvas></div>`;
  const pixelSteps=()=>{const t=S.tracking;return [['Meta connected',!!t.metaConnected],['Dataset chosen',!!t.pixel],['Installed on the store',!!t.installed],['Events received',!!t.tested]];};
  function overview(){
    const counts=statusCounts(), pend=pending();
    const next=S.posts.filter(p=>p.scheduledAt&&!['cancelled','published'].includes(p.status)).sort((a,b)=>a.scheduledAt.localeCompare(b.scheduledAt));
    const stages=[
      ['Listen','Saved evidence to draft from',S.saved.length,'research'],
      ['Draft','Ideas written, not yet reviewed',counts.draft||0,'studio'],
      ['Approve','Waiting on your decision',pend.length,'studio'],
      ['Publish','Scheduled or held',(counts.scheduled||0)+(counts.held||0),'calendar'],
      ['Learn','Published samples to study',counts.published||0,'results']
    ];
    const mx=Math.max(1,...stages.map(x=>x[2]));
    const px=pixelSteps(), pxDone=px.filter(x=>x[1]).length;
    const today=dateKey(new Date().toISOString()), tomorrow=dateKey(new Date(Date.now()+864e5).toISOString());
    const groups=[['Today',[]],['Tomorrow',[]],['Later',[]]];
    next.slice(0,6).forEach(p=>{const k=dateKey(p.scheduledAt);groups[k===today?0:k===tomorrow?1:2][1].push(p);});
    const tiles=[
      ['01','Listen','competitor_scan',`${signals.length} conversations · ${S.saved.length} saved`,'research'],
      ['02','Make','ig_ad',`${pend.length} drafts need you`,'studio'],
      ['03','Ship','publish_queue',`${next.length} posts queued`,'calendar']
    ];
    const trace=S.activity.slice(0,5);
    return head(`${esc(S.brand.name)} / ${new Intl.DateTimeFormat('en-GB',{weekday:'short',day:'numeric',month:'short'}).format(new Date())}`,(S.onboarding?'Coldie drafted these from your onboarding. Nothing publishes until you approve it and connect a channel.':'Coldie listens, drafts and queues. You make the calls. Everything here is a local sample.'))+`
    ${S.onboarding?'':`<a class="ov-onboard" href="onboarding.html"><span class="eyebrow">Step 0</span><strong>Wake Coldie<b>_</b></strong><span>Four minutes: Coldie reads your site and drafts your ICPs and brand book. Everything here uses sample data until then.</span><span class="btn paper">Start onboarding →</span></a>`}
    <section class="ov-hero blue" aria-label="This week">
      <span class="ov-hero-field" aria-hidden="true"></span>
      <div class="ov-hero-copy">
        <span class="eyebrow">Coldie / this week</span>
        <h2 class="ov-hero-title">${pend.length} call${pend.length===1?'':'s'} to make.<br>${next.length} post${next.length===1?'':'s'} queued<b>_</b></h2>
        <p>Approve the drafts waiting on you and the queue keeps moving. Nothing publishes without a decision.</p>
        <div class="row">${link(`Review ${pend.length} item${pend.length===1?'':'s'} →`,'studio','paper')}${link('Open research','research','ghost')}</div>
      </div>
      <div class="ov-tiles">${tiles.map(([n,t,clip,sub,r],i)=>`<a class="ov-tile ${i===1?'is-paper':''}" href="#/${r}"><span class="ov-tile-num">${n}</span><strong>${t}</strong>${art(clip,{fit:1.1,dark:i===1?'#0000F2':'#00006A',light:i===1?'#F2F2F2':'#F2F2F2'})}<small>${sub}</small></a>`).join('')}</div>
    </section>
    ${(()=>{const ph=(S.onboarding?.products||[]).filter(x=>x.image);if(!ph.length)return '';return `<section class="ov-shelf" aria-label="Your product shelf"><div class="ov-panel-head"><h2>Your shelf</h2><a class="caption" href="#/brand">${ph.length} product photos · brand book →</a></div><div class="ov-shelf-row">${ph.slice(0,12).map(x=>`<a class="ov-shelf-item" href="${x.url?esc(x.url):'#/brand'}" ${x.url?'target="_blank" rel="noopener noreferrer"':''} title="${esc(x.name)}"><img src="${esc(x.image)}" alt="${esc(x.name)}" loading="lazy" referrerpolicy="no-referrer"><span>${esc(x.name)}</span></a>`).join('')}</div></section>`;})()}
    <div class="ov-grid">
      <div class="ov-main">
        <section class="ov-panel ov-shift">
          <div class="ov-panel-head"><h2>Coldie’s shift</h2><span class="ov-live"><i></i>${S.paused?'Queue paused':'On shift · sample'}</span></div>
          <div class="ov-shift-body">
            ${art('loading_screen',{cls:'ov-shift-art',fit:1.15,cell:2})}
            <div class="ov-shift-log">
              <ol id="agent-trace" class="ov-trace" aria-label="Coldie trace">${trace.map((a,i)=>`<li><span>${a.time&&Number.isFinite(Date.parse(a.time))?timeLabel(a.time):'--:--'}</span><b>${i===0?'&gt;':'·'}</b>${esc(a.text)}</li>`).join('')||'<li><span>--:--</span><b>&gt;</b>Idle. Your local actions appear here.</li>'}</ol>
              <form id="command-form" class="ov-command" autocomplete="off"><label class="sr-only" for="command-input">Tell Coldie what to do</label><input id="command-input" name="command" type="text" placeholder="Tell Coldie what to do next…"><button class="btn" type="submit">Run ↵</button></form>
              <div class="ov-chips">${[['scan reddit','Scan conversations'],['review approvals','Review approvals'],['check pixel','Check pixel'],['schedule','Open calendar']].map(([c,t])=>`<button type="button" data-action="cmd" data-cmd="${c}">${t}</button>`).join('')}</div>
            </div>
          </div>
        </section>
        <section class="ov-panel">
          <div class="ov-panel-head"><h2>This week’s loop</h2><span class="caption">Listen → learn</span></div>
          <div class="ov-loop">${stages.map((x,i)=>`<div class="loop-row"><span class="loop-num ${x[2]?'is-on':''}">0${i+1}</span><div><strong>${x[0]}</strong><small>${x[1]}</small></div><div class="loop-bar"><i style="width:${Math.round(x[2]/mx*100)}%"></i></div><strong class="mono">${x[2]}</strong>${link('Open',x[3],'secondary')}</div>`).join('')}</div>
        </section>
        <section class="ov-panel">
          <div class="ov-panel-head"><h2>Fresh signals</h2>${link('All research →','research','secondary')}</div>
          <div class="ov-signals">${signals.slice(0,3).map(s=>`<button type="button" class="ov-signal" data-action="open-signal" data-id="${s.id}">${platform(s.source,true)}<div><small>${esc(s.where)}</small><strong>${esc(s.title)}</strong></div><span class="badge">${esc(s.score)}</span></button>`).join('')}</div>
        </section>
      </div>
      <aside class="ov-side">
        <section class="ov-panel">
          <div class="ov-panel-head"><h2>Needs you</h2><span class="ov-count">${pend.length}</span></div>
          <div class="ov-cards">${pend.slice(0,3).map(p=>`<a class="ov-card" href="#/studio" data-action="edit-post" data-id="${p.id}">${platform(p.platform,true)}<div><strong>${esc(p.title)}</strong><small>${names[p.platform]} · ${label(p.status)}</small></div></a>`).join('')||'<p class="small muted">Nothing waiting. Nice.</p>'}</div>
          ${pend.length?`<div class="ov-panel-foot">${link(`Review all ${pend.length} →`,'studio','')}</div>`:''}
        </section>
        <section class="ov-panel">
          <div class="ov-panel-head"><h2>Scheduled</h2>${link('Calendar →','calendar','secondary')}</div>
          <div class="ov-sched">${groups.filter(g=>g[1].length).map(([g,ps])=>`<span class="caption">${g}</span>${ps.map(p=>`<button type="button" class="ov-slot" data-action="open-calendar" data-id="${p.id}"><div><strong>${esc(p.title)}</strong><small>${dateLabel(p.scheduledAt)} · ${timeLabel(p.scheduledAt)}</small></div>${platform(p.platform,true)}</button>`).join('')}`).join('')||'<p class="small muted">No scheduled posts yet.</p>'}</div>
        </section>
        <a class="ov-pixel blue" href="#/tracking">
          ${art('pixel_setup',{cls:'ov-pixel-art',fit:1.15})}
          <span class="eyebrow">Meta Pixel · Shopify</span>
          <strong>${pxDone}/4 set up<b>_</b></strong>
          <ul>${px.map(([t,ok])=>`<li class="${ok?'is-ok':''}">${ok?'■':'□'} ${t}</li>`).join('')}</ul>
          <span class="btn paper">${pxDone<4?'Finish setup →':'View events →'}</span>
        </a>
      </aside>
    </div>`;
  }
  function sourceReport(label, source, count, retryKey) {
    const s=source||{}, verified=Number.isInteger(s.verified)?`${s.verified} of ${count} verified`:'Verification not reported';
    return `<li><strong>${esc(label)}</strong> · ${esc([s.mode,s.provider].filter(Boolean).join(' / ')||'Live request')} · ${esc(s.status||'No status')} · ${esc(verified)}${s.error?` · ${esc(s.error)}`:''}${retryKey&&(!count||s.error)?` <button type="button" class="line-button" data-action="retry-source" data-src="${esc(retryKey)}">Retry ${esc(label)}</button>`:''}</li>`;
  }
  function namedRivals(){return (S.onboarding?.competitors||[]).map(c=>typeof c==='string'?c:c?.name).filter(Boolean);}
  function crawler(){const L=S.live||{};const lines=scanBusy?scanLines:(L.log||[]);const used=L.sourcesUsed||['reddit','x','instagram'];
    return `<section class="crawl-panel"><div class="crawl-viz wired ${scanBusy?'is-running':''}"><div id="crawl-telemetry" class="crawl-telemetry" aria-label="Scan log">${lines.map(l=>`<div><b>&gt;</b> ${esc(l)}</div>`).join('')||(isLive()?'<div>Live scan log</div>':'<div>idle · run a live scan</div>')}</div>${art('research_wired',{fit:1,cell:2,dark:'#00006A'})}<span class="caption">Live research</span></div><div class="crawl-copy"><div class="row"><span class="eyebrow" style="margin:0">Listen before you launch</span>${isLive()?'<span class="badge approved">Live</span>':S.onboarding?'':sampleNote}</div><h3 id="scan-title">${scanBusy?'Coldie is reading…':isLive()?`${signals.length} live conversations`:'Run a live scan'}</h3>${L.summary&&!scanBusy?`<p>${esc(L.summary)}</p>`:'<p>Search public conversations on the selected sources.</p>'}
    <form id="live-scan-form" class="fields"><label class="field"><span>What should Coldie listen for?</span><input name="query" data-prefill minlength="2" maxlength="200" required value="${esc(L.query||(S.scanBrief&&S.scanBrief.topic)||S.onboarding?.product||String(S.brand.line||'').split(/[.,]/)[0].split(/\s+/).slice(0,8).join(' '))}"></label><div class="src-chips">${['reddit','x','instagram'].map(id=>`<label class="chip"><input type="checkbox" name="src" value="${id}" ${used.includes(id)?'checked':''}>${names[id]}</label>`).join('')}</div><div class="row" style="flex-wrap:wrap"><button class="btn" type="submit" ${scanBusy?'disabled':''}>${scanBusy?'Scanning…':isLive()?'Retry live scan':'Run live scan'}</button>${isLive()&&!scanBusy?btn('Back to sample data','clear-live','secondary'):''}</div></form>${isLive()&&!scanBusy?`<div class="research-report" role="status"><strong>${esc(L.scanError||(!signals.length?'No conversations returned.':'Review the source before drafting.'))}</strong><p>${signals.length?'Next: open a post, inspect the evidence, then draft an angle.':'Next: try fewer keywords or change sources, then retry.'}</p><ul>${used.map(k=>sourceReport(names[k],L.sources?.[k],L.sources?.[k]?.count??0,k)).join('')}</ul>${L.quality?`<p>${esc(L.quality.found??'—')} found · ${esc(L.quality.shown??signals.length)} shown · ${esc(L.quality.offTopic??0)} filtered as off-topic</p>`:''}${L.ai?`<small>Tagging: ${esc(L.ai)}</small>`:''}</div>`:''}${(L.themes||[]).length&&!scanBusy?`<div class="theme-row">${L.themes.map(t=>`<span class="theme-chip" title="${esc(t.summary)}">${esc(t.name)}</span>`).join('')}</div>`:''}</div></section>`;}
  function research(){let html=head('Research / evidence first','Find conversations, understand the category, and study the brands around you.',(U.research==='competitors'?adsLive():U.research==='signals'&&isLive())?'<span class="badge">Live research</span>':U.research==='saved'?'<span class="badge">Bookmarked evidence</span>':S.onboarding?'':sampleNote)+`<div class="subtabs" aria-label="Research sections">${[['signals','Conversations'],['category','Product category'],['competitors','Brand competitors'],['saved',`Saved (${S.saved.length})`]].map(([id,n])=>`<button type="button" data-research="${id}" aria-pressed="${U.research===id}">${n}</button>`).join('')}</div>`;
    if(['signals','saved'].includes(U.research)){
      const filtered=signals.filter(s=>(U.research!=='saved'||S.saved.includes(s.id))&&U.sources.includes(s.source)&&(U.intent==='all'||s.intent===U.intent)&&(U.topic==='all'||s.topic===U.topic)&&(s.title+' '+s.body+' '+s.topic).toLowerCase().includes(U.query.toLowerCase()));
      const savedTd=U.research==='saved'?teardowns.filter(t=>S.saved.includes(t.id)):[];const moment=`<p class="display research-moment">The internet is talking<span class="blink">_</span></p><p class="small muted" style="margin:2px 0 14px">${isLive()?`${filtered.length} live conversations · ${esc(S.live.query)} · ${agoLabel(S.live.at)}`:(S.onboarding?`No conversations yet · run a live scan for ${esc(S.brand.name)}`:`${filtered.length} sample conversations worth a look · run a live scan to replace them`)}</p>`;
      const s=filtered.find(s=>s.id===U.signal)||filtered[0];if(s)U.signal=s.id;
      return html+moment+(U.research==='signals'?crawler():'')+`<div class="toolbar"><div class="toolbar-group"><label class="field"><span class="sr-only hidden">Search conversations</span><input id="signal-search" type="search" aria-label="Search conversations" placeholder="Search conversations…" value="${esc(U.query)}"></label><span class="caption">${filtered.length} ${isLive()?'live':S.onboarding?'':'sample'} signals</span></div><span class="caption muted">${isLive()?'Live scan · '+esc(S.live.ai||'no tagging reported'):S.onboarding?'':'Illustrative evidence, not live results'}</span></div>${savedTd.length?`<section class="panel" style="margin-bottom:16px"><div class="panel-head"><h2>Saved competitor evidence</h2><span class="caption">${savedTd.length} cards</span></div>${savedTd.map(t=>`<div class="list-row"><span class="badge ${t.channel==='paid'?'sample-badge':'approved'}">${t.channel}</span><div class="grow"><strong>${esc(t.brand)} · ${esc(t.format)}</strong><small>${esc(t.hook)}</small></div>${btn('Draft angle','teardown-draft','secondary',`data-id="${t.id}"`)}</div>`).join('')}</section>`:''}<div class="research-layout"><aside class="filter-rail"><div class="sources"><h3>Sources</h3>${['reddit','x','instagram'].map(id=>`<label><input type="checkbox" data-source="${id}" ${U.sources.includes(id)?'checked':''}>${platform(id)}</label>`).join('')}</div><div class="intents"><h3>Intent</h3><div class="intent-list">${['all','Customer pain','Buying intent','Product feedback','Competitor gap','Content idea'].map(n=>`<button type="button" class="intent-btn" data-intent="${n}" aria-pressed="${U.intent===n}">${n==='all'?'All':n}<span class="mono">${n==='all'?signals.length:signals.filter(s=>s.intent===n).length}</span></button>`).join('')}</div></div><div class="topics"><h3>Topics</h3><div class="topic-cloud">${['all',...[...new Set(signals.map(s=>s.topic).filter(Boolean))].slice(0,8)].map(t=>`<button type="button" class="topic-btn" data-topic="${esc(t)}" aria-pressed="${U.topic===t}">${t==='all'?'All topics':esc(t)}</button>`).join('')}</div></div></aside><div class="signal-list">${filtered.map(s=>`<button type="button" class="signal-item" data-signal="${s.id}" aria-selected="${s.id===U.signal}"><div class="signal-meta">${platform(s.source,true)}<span>${esc(s.where)}</span><span class="relevance-pill">${esc(s.score)}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.body.slice(0,110))}…</p><div class="signal-bottom"><span class="badge">${esc(s.intent)}</span><span class="caption">${esc(s.up)} · ${S.saved.includes(s.id)?'Saved ✓':s.live?`${s.verified?'Verified':'Not verified'} · ${esc(s.tagged||'Tagging not reported')}`:'Sample'}</span></div></button>`).join('')||(S.onboarding&&!isLive()&&U.research==='signals'?C.empty(`No research for ${esc(S.brand.name)} yet`,`Run a live scan above. Coldie searches public conversations about “${esc(S.onboarding.product||S.onboarding.category||'your product')}” and tags each one by intent.`):C.empty('No matching signals','Change your filters or save a conversation from the Conversations tab.'))}</div>${s?`<aside class="inspector"><div class="panel-head"><h2>Evidence → action</h2><button class="icon-btn" data-action="save-signal" data-id="${s.id}" aria-label="${S.saved.includes(s.id)?'Unsave':'Save'} signal" aria-pressed="${S.saved.includes(s.id)}">${icon('save')}</button></div><div class="inspector-body">${platform(s.source)}<h3>${esc(s.title)}</h3><blockquote>“${esc(s.body)}”</blockquote><span class="evidence-type">${esc(s.evidence)}${s.url?` · <a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}</span>${s.rule?`<p class="small muted">${esc(s.rule)}</p>`:''}${C.insight(s.live?'COLDIE’S READ / CHECK THE SOURCE':'PROPOSED ANGLE / NOT A FINDING',esc(s.insight))}<div><span class="eyebrow">Content brief</span><p class="small">${esc(s.angle)}</p></div><div class="actions">${btn('Turn into a draft '+icon('arrow'),'signal-draft','',`data-id="${s.id}"`)}</div></div></aside>`:''}</div>`;
    }
    if(U.research==='category')return html+`<div class="blue-note"><div class="grow"><span class="eyebrow">Category lens / plant-care products</span><h3>What are customers trying to solve?</h3><p>Illustrative synthesis. Category research compares needs and alternatives—not just named brands.</p></div>${btn('Edit research brief','category-brief','secondary')}</div><div class="research-summary">${[['01 / Job to be done','A routine that sticks','Know what to do, when to do it, and which tools are actually useful.'],['02 / Alternatives','Simple beats more','A finger test, a reminder, a care guide, or a complete starter kit. Compare the job each serves.'],['03 / Messaging gap','Show the whole routine','A practical demonstration may answer the question better than another product-only image.']].map(x=>`<section class="research-note"><span class="caption">${x[0]}</span><h3>${x[1]}</h3><p class="muted">${x[2]}</p></section>`).join('')}</div><section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Evidence by research surface</h2>${sampleNote}</div><div class="table-wrap"><table class="comparison"><thead><tr><th>Surface</th><th>What to compare</th><th>What not to assume</th></tr></thead><tbody><tr><td><strong>Reddit + X</strong>Customer conversations</td><td>Pain, alternatives, objections and questions</td><td>One conversation is not a market-size estimate.</td></tr><tr><td><strong>Instagram organic</strong>Category content</td><td>Formats, hooks, demonstrations and recurring themes</td><td>Visible engagement does not prove sales.</td></tr><tr><td><strong>Meta Ad Library</strong>Paid creative evidence</td><td>Offers, creative variants, destinations and dates where available</td><td>Ad visibility does not establish ROAS.</td></tr></tbody></table></div></section><div class="actions" style="margin-top:20px">${btn('Draft from this category brief','category-draft')}</div>`;
    const tds=teardowns.filter(t=>(U.compBrand==='all'||t.brand===U.compBrand)&&(U.compChannel==='all'||t.channel===U.compChannel));
    return html+`<div class="blue-note">${miniArt('competitor_scan')}<div class="grow"><span class="eyebrow">Brand lens / named competitors</span><h3>Separate what they post from what they advertise.</h3><p>${adsLive()?`${teardowns.length} live ads for “${esc(S.live.adsQuery)}” · ${agoLabel(S.live.adsAt)}`:'Fictional comparison records until you pull live ads. Organic Instagram and Meta paid creative remain separate evidence types.'}</p></div></div>
    <form id="live-ads-form" class="live-ads-bar"><label class="field grow"><span>Category or product (the shopper’s words)</span><input name="query" data-prefill minlength="2" required maxlength="200" value="${esc(S.live?.adsQuery||S.live?.query||S.onboarding?.product||S.onboarding?.category||'')}" placeholder="${S.onboarding?'e.g. '+esc(S.onboarding.product||S.onboarding.category||'your product'):'e.g. plant care kit'}"></label><label class="field"><span>Named rival (optional)</span><input name="rival" list="research-rivals" value="${esc(S.live?.adsRival??namedRivals()[0]??'')}" placeholder="All advertisers"><datalist id="research-rivals">${namedRivals().map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist></label><label class="field"><span>Country</span><select name="country">${['US','GB','IN','CA','AU','DE','FR'].map(c=>`<option ${(S.live?.adsCountry||(S.onboarding?.currency==='INR'||/\.in$/i.test((S.brand.url||'').replace(/\/.*$/,'').replace(/^https?:\/\//,''))?'IN':S.onboarding?.currency==='GBP'?'GB':S.onboarding?.currency==='CAD'?'CA':S.onboarding?.currency==='AUD'?'AU':'US'))===c?'selected':''}>${c}</option>`).join('')}</select></label><button class="btn" type="submit" ${adsBusy?'disabled':''}>${adsBusy?'Pulling ads…':adsLive()?'Retry ad search':'Pull Meta Ad Library'}</button></form>${adsLive()&&!adsBusy?`<div class="research-report" role="status"><strong>${S.live.adsRival?'Named rival':'Category'} search · ${esc(S.live.adsNote||(teardowns.length?'Ads returned':'No ads returned'))}</strong><ul>${sourceReport('Meta Ad Library',S.live.adsSource,teardowns.length)}</ul><p>Next: ${teardowns.length?'inspect an ad before drafting.':'change the rival, keywords or country, then retry.'}</p></div>`:''}
    <div class="comp-filter-bar">${C.seg('data-comp-filter',[['all','All brands'],...[...new Set(teardowns.map(t=>t.brand))].slice(0,6).map(b=>[esc(b),esc(b)])],U.compBrand)}${C.seg('data-comp-channel',[['all','All evidence'],['paid','Meta Ad Library'],['organic','Instagram organic']],U.compChannel)}<span class="caption muted">${adsLive()?'Live Meta Ad Library':S.onboarding?'Nothing pulled yet':'Designed samples: not scraped ad data'}</span></div>
    <div class="teardown-grid">${tds.map(t=>teardownCard(t)).join('')||(S.onboarding&&!adsLive()?C.empty('No competitor ads pulled yet','Use Pull Meta Ad Library above to see real ads in your category or from a named rival. Nothing here is invented.'):C.empty('No cards match','Try another brand or evidence channel.'))}</div>
    <section class="panel" style="margin-top:4px"><div class="panel-head"><h2>Competitor comparison</h2><span class="caption">${competitorData.length} ${adsLive()?'live':'example'} brands</span></div><div class="table-wrap"><table class="comparison"><thead><tr><th>Brand / positioning</th><th>Instagram · organic</th><th>Meta library · paid</th><th>Potential angle</th></tr></thead><tbody>${competitorData.map((c,i)=>`<tr><td><strong>${esc(c.name)}</strong><span class="muted">${esc(c.position)}</span></td><td>${esc(c.organic)}</td><td>${esc(c.paid)}<br><span class="caption muted">${adsLive()?'Live Ad Library · no performance data':'Sample creative · no performance data'}</span></td><td>${esc(c.gap)}<br><button class="line-button" style="margin-top:10px" data-action="competitor-detail" data-index="${i}">Inspect evidence →</button></td></tr>`).join('')}</tbody></table></div></section><p class="notice" style="margin-top:18px">Production coverage depends on source access. Missing data must be labelled—not invented or treated as zero.</p>`;
  }
  function creative(p){const words=p.title.split(' ');const l1=words.slice(0,3).join(' ').slice(0,24);const l2=words.slice(3,7).join(' ').slice(0,26);return `<svg viewBox="0 0 400 500" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Generated sample creative"><rect width="400" height="500" fill="#0000F2"/><rect x="0" y="0" width="400" height="64" fill="#9C9CFF" opacity=".22"/><rect x="28" y="92" width="70" height="9" fill="#ECEA36"/><text x="28" y="152" fill="#F2F2F2" font-family="Zen Dots, sans-serif" font-style="italic" font-size="29">${esc(l1)}</text>${l2?`<text x="28" y="192" fill="#F2F2F2" font-family="Zen Dots, sans-serif" font-style="italic" font-size="29">${esc(l2)}</text>`:''}<rect x="28" y="428" width="150" height="36" fill="#111C4A"/><text x="42" y="451" fill="#F5F3EB" font-family="DM Mono, monospace" font-size="14">${esc(S.brand.name.slice(0,14))}</text><rect x="312" y="428" width="60" height="36" fill="#ECEA36"/></svg>`;}
